"use client"

import type { ReactNode } from "react"

import { attemptCount, needsDecision, taskCost } from "@/lib/agent-task-board-model"
import type { TaskLink, TaskView, ThreadRef } from "@/lib/agent-task-types"
import { cn } from "@/lib/utils"
import { AcceptanceList } from "@/components/ui/acceptance-list"
import { agentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { AttachmentStrip } from "@/components/ui/attachments"
import { AttemptTimeline } from "@/components/ui/attempt-timeline"
import { DependencyChips } from "@/components/ui/dependency-chips"
import { ProposalActions } from "@/components/ui/proposal-actions"
import { RelativeTime } from "@/components/ui/relative-time"
import { TaskStatusIcon, TaskStatusPill, taskStatusTones } from "@/components/ui/task-status"
import { proposalError, type TaskDisplayOptions } from "@/components/ui/task-card"
import { Block, DetailValue } from "@/components/ui/task-detail-parts"
import { TaskLinks } from "@/components/ui/task-links"
import { TaskLocationTrack } from "@/components/ui/task-location"
import { UsageGrid } from "@/components/ui/usage-grid"

type TaskDetailContentProps = TaskDisplayOptions & {
  task: TaskView
  renderThreadLink?: (thread: ThreadRef) => ReactNode
  onOpenThread?: (thread: ThreadRef) => void
  /** Replaces the default link in the detail's list of links. */
  renderLink?: (link: TaskLink) => ReactNode
  /** Replaces the attachment strip in the main column. */
  renderAttachments?: (task: TaskView) => ReactNode
  /** Replaces the stage track in the side column. */
  renderLocation?: (task: TaskView) => ReactNode
  /**
   * `"split"` sets the side column beside the main one once the content is 56rem wide, inside an
   * `@container/task-detail`; `"stack"` (default) keeps one column, the side after the main.
   */
  layout?: "stack" | "split"
  /** Lists the status among the details; turn it off where a header already shows it. */
  showStatus?: boolean
  /** Heading level of each section. */
  headingLevel?: number
}

function TaskDetailMeta({
  task,
  labels = agentTaskBoardLabels,
}: {
  task: TaskView
  labels?: TaskDisplayOptions["labels"]
}) {
  return (
    <div className="flex flex-wrap items-center gap-items text-xs">
      <span className="font-mono text-muted-foreground">{task.id}</span>
      <TaskStatusIcon status={task.status} />
      <TaskStatusPill status={task.status} labels={labels?.components.taskStatus} />
    </div>
  )
}

function TaskDetailContent({
  task,
  mode = "snapshot",
  now,
  locale,
  timeZone,
  formatCurrency,
  labels = agentTaskBoardLabels,
  onApproveProposal,
  onRejectProposal,
  agentApproval,
  onSelectTask,
  canSelect,
  renderThreadLink,
  onOpenThread,
  renderLink,
  onOpenLink,
  renderAttachments,
  renderLocation,
  agentAvatars,
  statusTones,
  stages,
  layout = "stack",
  showStatus = true,
  headingLevel = 3,
}: TaskDetailContentProps) {
  const text = labels.panel
  const parts = labels.components
  const time = { now, locale, timeZone }
  const selectable = onSelectTask && task.dependsOn.some((dependency) => canSelect?.(dependency.id) ?? true)
  const counts = task.counts
  const attachments = renderAttachments
    ? renderAttachments(task)
    : task.attachments &&
      task.attachments.length > 0 && (
        <AttachmentStrip
          attachments={task.attachments}
          aria-label={text.attachmentsOf(task.id)}
          labels={parts.attachments}
          locale={locale}
        />
      )
  const location = renderLocation
    ? renderLocation(task)
    : task.location && (
        <TaskLocationTrack location={task.location} stages={stages} aria-label={text.locationOf(task.id)} />
      )
  const links = task.links ?? []
  const split = layout === "split"

  return (
    <div
      data-slot="task-detail-content"
      data-layout={layout}
      className={cn(
        "flex min-w-0 flex-col gap-group",
        split &&
          "@4xl/task-detail:grid @4xl/task-detail:grid-cols-(--task-detail-columns) @4xl/task-detail:items-start @4xl/task-detail:gap-section",
      )}
    >
      <div data-slot="task-detail-main" className="flex min-w-0 flex-col gap-group">
        {task.goal && (
          <Block title={text.goal} level={headingLevel}>
            <p className="text-sm whitespace-pre-line">{task.goal}</p>
          </Block>
        )}

        {needsDecision(task) && (
          <Block title={text.decision} level={headingLevel}>
            {task.decisionNeeded && <p className="text-sm">{task.decisionNeeded}</p>}
            {task.status === "proposed" && (
              <ProposalActions
                taskId={task.id}
                mode={mode}
                onApprove={onApproveProposal}
                onReject={onRejectProposal}
                agentApproval={agentApproval}
                labels={labels.proposals}
                renderError={(error) => proposalError(error, labels)}
              />
            )}
          </Block>
        )}

        <Block title={text.acceptance} level={headingLevel}>
          {task.acceptance.length > 0 ? (
            <AcceptanceList
              criteria={task.acceptance}
              labels={parts.acceptance}
              evidence="disclosure"
              className="gap-inline"
            />
          ) : (
            <p className="text-sm text-muted-foreground">{text.noAcceptance}</p>
          )}
        </Block>

        {attachments ? (
          <Block title={text.attachments} level={headingLevel}>
            {attachments}
          </Block>
        ) : null}

        <Block title={text.activity} level={headingLevel}>
          {task.attempts.length > 0 ? (
            <AttemptTimeline
              attempts={task.attempts}
              labels={{ ...parts.attemptTimeline, threadLink: labels.openThread }}
              usageLabels={parts.usage}
              usageOpenUpTo={0}
              agentAvatars={agentAvatars}
              formatCurrency={formatCurrency}
              renderThreadLink={renderThreadLink}
              onOpenThread={onOpenThread}
              {...time}
            />
          ) : (
            <p className="text-sm text-muted-foreground">{labels.empty.attempts}</p>
          )}
        </Block>
      </div>

      <div data-slot="task-detail-side" className="flex min-w-0 flex-col gap-group">
        <dl className="grid grid-cols-(--detail-value-columns) content-start gap-x-group gap-y-items text-sm">
          {showStatus && (
            <DetailValue term={text.status}>
              <span className="inline-flex items-center gap-inline">
                <TaskStatusIcon status={task.status} tone={statusTones?.[task.status]} />
                <span>{parts.taskStatus?.[task.status] ?? labels.columns[task.status]}</span>
              </span>
            </DetailValue>
          )}
          {task.profile && <DetailValue term={text.profile}>{task.profile}</DetailValue>}
          {task.project && <DetailValue term={text.project}>{task.project}</DetailValue>}
          <DetailValue term={text.updated}>
            <RelativeTime value={task.updatedAt} {...time} />
          </DetailValue>
          {!task.usage && (
            <DetailValue
              term={text.cost}
              quantity={taskCost(task)}
              locale={locale}
              formatCurrency={formatCurrency}
              quantityLabels={parts.usage?.quantity}
            />
          )}
          {task.labels && task.labels.length > 0 && (
            <DetailValue term={text.labels} wrap>
              <ul className="flex flex-wrap gap-inline">
                {task.labels.map((label) => (
                  <li
                    key={label}
                    className="rounded-control border bg-secondary px-inset-chip py-inset-chip text-xs text-secondary-foreground"
                  >
                    {label}
                  </li>
                ))}
              </ul>
            </DetailValue>
          )}
        </dl>

        {task.dependsOn.length > 0 && (
          <Block title={text.dependencies} level={headingLevel}>
            <DependencyChips
              aria-label={text.dependenciesOf(task.id)}
              items={task.dependsOn.map((dependency) => ({
                id: dependency.id,
                label: `${dependency.id} ${dependency.title ?? ""}`.trim(),
                tone: taskStatusTones[dependency.status],
              }))}
              onSelect={selectable ? (id) => (canSelect?.(id) ?? true) && onSelectTask?.(id) : undefined}
            />
          </Block>
        )}

        <Block title={text.attemptsSummary} level={headingLevel}>
          <dl className="grid grid-cols-(--detail-value-columns) gap-x-group gap-y-inline text-sm">
            <DetailValue term={text.counts.attempts} inline>
              {counts?.attempts ?? attemptCount(task)}
            </DetailValue>
            {counts && (
              <>
                <DetailValue term={text.counts.repairs} inline>
                  {counts.repairs}
                </DetailValue>
                <DetailValue term={text.counts.reviews} inline>
                  {counts.reviews}
                </DetailValue>
                <DetailValue term={text.counts.humanInterventions} inline>
                  {counts.humanInterventions}
                </DetailValue>
              </>
            )}
            {task.acceptedFirstPass !== undefined && (
              <DetailValue term={text.acceptedFirstPass} inline>
                {task.acceptedFirstPass ? text.yes : text.no}
              </DetailValue>
            )}
          </dl>
        </Block>

        {task.usage && (
          <Block title={text.usage} level={headingLevel}>
            <UsageGrid
              usage={task.usage}
              variant="compact"
              aria-label={text.usageOf(task.id)}
              labels={parts.usage}
              locale={locale}
              formatCurrency={formatCurrency}
            />
          </Block>
        )}

        {links.length > 0 && (
          <Block title={text.links} level={headingLevel}>
            <TaskLinks
              links={links}
              aria-label={text.linksOf(task.id)}
              labels={labels.link}
              renderLink={renderLink}
              onOpenLink={onOpenLink && ((link) => onOpenLink(link, task))}
            />
          </Block>
        )}

        {location ? (
          <Block title={text.location} level={headingLevel}>
            {location}
          </Block>
        ) : null}
      </div>
    </div>
  )
}

export { TaskDetailContent, TaskDetailMeta }
export type { TaskDetailContentProps }

"use client"

import { useState, type ComponentProps } from "react"

import type { TaskView } from "@/lib/agent-task-types"
import { cn } from "@/lib/utils"
import { agentTaskBoardLabels } from "@/components/ui/agent-task-labels"
import { Dialog, DialogBackdrop, DialogBody, DialogClose, DialogContent, DialogTitle } from "@/components/ui/dialog"
import { Drawer, DrawerBackdrop, DrawerClose, DrawerContent, DrawerTitle } from "@/components/ui/drawer"
import { TaskDetailContent, type TaskDetailContentProps } from "@/components/ui/task-detail-content"
import { CloseIcon } from "@/components/ui/task-detail-parts"
import type { CloseReason } from "@/components/ui/task-detail-panel"

type TaskDetailDialogProps = Omit<TaskDetailContentProps, "task" | "headingLevel" | "layout" | "showStatus"> & {
  /** The task to show; `undefined` closes the dialog. */
  task: TaskView | undefined
  presentation?: "dialog" | "drawer"
  /** Runs when a person or an agent closes it; clear the task to close it, or keep it to refuse. */
  onClose: (reason: CloseReason | "imperative") => void
  /** Where focus goes once it closes; the element focused before it opened by default. */
  finalFocus?: ComponentProps<typeof DialogContent>["finalFocus"]
  className?: string
}

const parts = {
  dialog: {
    Root: Dialog,
    Backdrop: DialogBackdrop,
    Content: DialogContent,
    Title: DialogTitle,
    Close: DialogClose,
    Body: DialogBody,
  },
  drawer: {
    Root: Drawer,
    Backdrop: DrawerBackdrop,
    Content: DrawerContent,
    Title: DrawerTitle,
    Close: DrawerClose,
    Body: DrawerBody,
  },
}

function DrawerBody({ className, ...props }: ComponentProps<"div">) {
  return <div className={cn("flex min-h-0 flex-1 flex-col overflow-y-auto overscroll-contain", className)} {...props} />
}

const shapes = {
  dialog: "gap-0 overflow-hidden p-0",
  drawer: "gap-0 overflow-hidden p-0 data-[side=right]:max-w-xl",
}

function closeReason(reason: string): CloseReason | "imperative" {
  return reason === "close-press" || reason === "escape-key" || reason === "outside-press" ? reason : "imperative"
}

function TaskDetailDialog({
  task,
  presentation = "dialog",
  onClose,
  finalFocus,
  className,
  labels = agentTaskBoardLabels,
  ...content
}: TaskDetailDialogProps) {
  // Keeps the last task on screen while the dialog animates out.
  const [shown, setShown] = useState(task)
  if (task && task !== shown) setShown(task)
  const current = task ?? shown
  const { Root, Backdrop, Content, Title, Close, Body } = parts[presentation]

  return (
    <Root
      open={task !== undefined}
      onOpenChange={(open, details) => {
        if (!open) onClose(closeReason(details.reason))
      }}
      {...(presentation === "drawer" ? { side: "right" as const } : {})}
    >
      <Backdrop />
      <Content
        data-task-detail={presentation}
        data-task-id={current?.id}
        initialFocus="content"
        finalFocus={finalFocus}
        {...(presentation === "dialog" ? { size: "xl" as const } : {})}
        className={cn("flex flex-col", shapes[presentation], className)}
      >
        {current && (
          <>
            <div className="flex shrink-0 items-start gap-items border-b px-inset-surface py-group">
              <Title data-slot="task-detail-title" className="min-w-0 flex-1 text-title-sm leading-snug">
                <span className="font-mono text-muted-foreground">{current.id}</span> {current.title}
              </Title>
              <Close variant="ghost" size="icon" aria-label={labels.panel.close}>
                <CloseIcon />
              </Close>
            </div>
            <Body className="@container/task-detail mx-0 p-inset-surface">
              <TaskDetailContent
                task={current}
                labels={labels}
                {...content}
                layout={presentation === "dialog" ? "split" : "stack"}
                headingLevel={3}
              />
            </Body>
          </>
        )}
      </Content>
    </Root>
  )
}

export { TaskDetailDialog }
export type { TaskDetailDialogProps }

"use client"

import type { ReactNode } from "react"

import { formatQuantity, type Quantity, type QuantityLabels } from "@/lib/quantity"
import { cn } from "@/lib/utils"
import { QuantityValue } from "@/components/ui/quantity-value"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { usageFormatter } from "@/components/ui/usage"

type DetailValueProps = {
  term: string
  children?: ReactNode
  /** Shown instead of `children`; an estimate or a sourced value gets a tooltip saying so. */
  quantity?: Quantity
  locale?: string
  formatCurrency?: (usd: number) => string
  quantityLabels?: Partial<QuantityLabels>
  /** Term and value on one row. */
  inline?: boolean
  /** Lets the value wrap instead of truncating. */
  wrap?: boolean
}

function DetailValue({
  term,
  children,
  quantity,
  locale,
  formatCurrency,
  quantityLabels,
  inline = false,
  wrap = false,
}: DetailValueProps) {
  let value = children
  if (quantity) {
    const format = usageFormatter("cost", { locale, formatCurrency })
    const hint = formatQuantity(quantity, {
      format,
      locale,
      labels: quantityLabels,
    }).title
    const shown = (
      <QuantityValue value={quantity} format={format} locale={locale} labels={quantityLabels} title={undefined} />
    )
    value = hint ? (
      <Tooltip>
        <TooltipTrigger
          aria-label={`${term}: ${formatQuantity(quantity, { format, locale, labels: quantityLabels }).srText}`}
          className="cursor-help rounded-control underline decoration-dotted underline-offset-4 outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {shown}
        </TooltipTrigger>
        <TooltipContent>{hint}</TooltipContent>
      </Tooltip>
    ) : (
      shown
    )
  }
  return (
    <div
      data-slot="task-detail-value"
      className={cn("flex min-w-0 gap-inline", inline ? "items-baseline justify-between" : "flex-col")}
    >
      <dt className="min-w-0 truncate text-xs text-muted-foreground">{term}</dt>
      <dd className={cn("min-w-0", wrap ? "wrap-anywhere" : "truncate", inline && "shrink-0 tabular-nums")}>{value}</dd>
    </div>
  )
}

// Escape inside a popup the panel holds (a reject confirmation, a tooltip) belongs to that popup.
function insidePopup(target: EventTarget, panel: Element) {
  const popup = target instanceof Element ? target.closest('[role="dialog"],[role="alertdialog"],[popover]') : null
  return popup !== null && popup !== panel && panel.contains(popup)
}

function Block({
  title,
  level,
  className,
  children,
}: {
  title: string
  level: number
  className?: string
  children: ReactNode
}) {
  const Heading = `h${Math.min(level, 6)}` as "h3"
  return (
    <section className={cn("flex flex-col gap-inline", className)}>
      <Heading className="text-meta tracking-meta text-muted-foreground uppercase">{title}</Heading>
      {children}
    </section>
  )
}

function CloseIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <path d="M18 6 6 18M6 6l12 12" />
    </svg>
  )
}

export { Block, CloseIcon, DetailValue, insidePopup }
export type { DetailValueProps }
